def balanced(s):
    """Return True if all brackets in s are balanced and properly nested.

    Brackets inside double-quoted strings are ignored. Within a quoted
    string, a backslash escapes the following character. An unterminated
    string makes the input unbalanced.
    """
    pairs = {
        ')': '(',
        ']': '[',
        '}': '{',
    }
    opening = '([{'
    closing = ')]}'
    stack = []
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if ch == '"':
            i += 1
            terminated = False
            while i < n:
                if s[i] == '\\':
                    i += 2
                elif s[i] == '"':
                    i += 1
                    terminated = True
                    break
                else:
                    i += 1
            if not terminated:
                return False
            continue

        if ch in opening:
            stack.append(ch)
        elif ch in closing:
            if not stack or stack.pop() != pairs[ch]:
                return False

        i += 1

    return not stack
